package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.Map;

/**
 * A year end rollover: the old fiscal year's name (FY<yyyy>), the new year's first period (null when there is none),
 * and each person's open figure at the end of the old year, by person id in sheet order.
 */
public record Rollover(String fy, Period first, Map<Long, BigDecimal> openings) {
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.Comparator;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateRollover {

    private static final Pattern YEAR = Pattern.compile("\\d{4}");

    // A year (yyyy), rolled over only by a steward, and only when the fiscal year FY<yyyy> has a period (one starting
    // within it). The next fiscal year is generated as the fiscal year generator does; each person's open figure at the
    // end of the old year's last period goes to the new year's first period (the one holding its first day).
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody GenerateFiscalYearRequest body,
            Periods periods, Settings settings, Rollup rollup, ServerHttpConnection connection,
            Out<GeneratedPeriods> generatedOut, Out<Rollover> rolloverOut) throws InvalidPeriodException, PeriodRefusedException {
        String year = body == null || body.year() == null ? "" : body.year().trim();
        if (!YEAR.matcher(year).matches()) {
            throw new InvalidPeriodException("The fiscal year must be a year (yyyy).");
        }
        String sheet = sheetId.trim();
        if (!Settings.STEWARD.equals(settings.role(sheet, Audit.user(connection).trim()))) {
            throw new PeriodRefusedException("Only a steward rolls the year over.");
        }
        YearMonth start = YearMonth.of(Integer.parseInt(year), settings.fiscalStartMonth(sheet));
        LocalDate from = start.atDay(1);
        LocalDate next = start.plusMonths(12).atDay(1);
        List<Period> existing = periods.list(sheet);
        List<Period> old = existing.stream().filter(p -> !p.from().isBefore(from) && p.from().isBefore(next)).toList();
        if (old.isEmpty()) {
            throw new PeriodRefusedException("The fiscal year FY" + year + " has no periods.");
        }
        Period last = old.stream().max(Comparator.comparing(Period::to)).orElseThrow();
        YearMonth newStart = start.plusMonths(12);
        GeneratedPeriods generated = GeneratedPeriods.months(sheet, existing, newStart, newStart.plusMonths(11));
        Period first = generated.periods().stream().filter(p -> p.contains(next)).findFirst()
                .orElseGet(() -> periods.on(sheet, next));
        generatedOut.set(generated);
        rolloverOut.set(new Rollover("FY" + year, first, rollup.personOpenAt(sheet, old, last.to())));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class SetRolloverOpenings {
    // Each person's open figure at the old year's end (any above 0.00) is added to their opening balance for the new
    // year's first period, in sheet order (OPENING_SET); then the rollover itself is recorded (ROLLOVER).
    public void set(@PathVariable("sheetId") String sheetId, @Val Rollover rollover, @Val GeneratedPeriods generated,
            Periods periods, People people, ServerHttpConnection connection, Audit audit) {
        String sheet = sheetId.trim();
        String user = Audit.user(connection);
        if (rollover.first() != null) {
            for (Person person : people.list(sheet)) {
                BigDecimal amount = rollover.openings().get(person.id());
                if (amount == null || amount.signum() <= 0) {
                    continue;
                }
                periods.addOpening(sheet, rollover.first().name(), person.id(), amount);
                audit.record(Audit.line("OPENING_SET", sheet, user, "name=" + person.name(),
                        "period=" + rollover.first().name(), "amount=" + amount.toPlainString()));
            }
        }
        audit.record(Audit.line("ROLLOVER", sheet, user, "fy=" + rollover.fy(),
                "periods=" + generated.periods().size()));
    }
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, RefusedError } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { useUser } from '../session/useUser';
import { periodsKey } from './periodsQuery';

const YEAR = /^\d{4}$/;

/**
 * The year end rollover: a steward types a fiscal year (yyyy) that has periods. The server makes the next fiscal
 * year's twelve months as the fiscal year generator does and carries each person's open figure at the old year's end
 * into the new year's first period as an opening balance. Shows how many periods it made.
 */
function Rollover({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [year, setYear] = useState('');
  const [error, setError] = useState('');
  const [made, setMade] = useState('');
  const once = useSubmitOnce();
  const rollover = useMutation({
    mutationFn: (body: { year: string }) =>
      postJson<{ made: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/periods/rollover`, body, user),
    onSuccess: async (r) => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
      setMade(String(r.made));
    },
    onError: (e) =>
      setError(e instanceof RefusedError ? e.message : 'The year could not be rolled over: only a steward rolls over a fiscal year (yyyy) that has periods.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setMade('');
    const y = year.trim();
    if (!YEAR.test(y)) {
      setError('The fiscal year must be a year (yyyy).');
      return;
    }
    once(() => rollover.mutateAsync({ year: y }));
  };

  return (
    <form data-testid="rollover-form" onSubmit={submit}>
      <label>
        Roll over fiscal year{' '}
        <input
          data-testid="rollover-year"
          placeholder="yyyy"
          value={year}
          onChange={(e) => {
            setYear(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="rollover" disabled={rollover.isPending}>
        Roll year over
      </button>{' '}
      Made: <span data-testid="rollover-made">{made}</span>
      {error && <p data-testid="rollover-error">{error}</p>}
    </form>
  );
}

// Below the opening balances; keyed by sheet, so a year, a count or an error never carries over.
export const contribution = SheetPanel.fill({
  order: 7.2,
  Component: ({ sheetId }) => <Rollover key={sheetId} sheetId={sheetId} />,
});
